60.     /// </summary>
61.     /// <param name="input">The PascalCase or camelCase string to convert.</param>
62.     /// <returns>A human-readable string with words separated by spaces.</returns>
63.     /// <example>
64.     /// <code>
65.     /// "SomePropertyName".Titleize() => "Some Property Name"
66.     /// "firstName".Titleize() => "First Name"
67.     /// </code>
68.     /// </example>
69.     public static string Titleize(this string input)
70.     {
71.         if (string.IsNullOrWhiteSpace(input))
72.         {
73.             return input;
74.         }
75. 
76.         return CamelCaseBoundary()
77.             .Replace(input, " ")
78.             .Replace('_', ' ')
79.             .Trim();
80.     }
