216. /// <summary>
217. /// Represents an inflection rule that uses a regex pattern to match and transform words.
218. /// Used by the vocabulary system to apply pluralization and singularization rules.
219. /// </summary>
220. internal class InflectionRule
221. {
222.     private readonly Regex _regex;
223.     private readonly string _replacement;
224. 
225.     /// <summary>
226.     /// Initializes a new instance of the <see cref="InflectionRule"/> class.
227.     /// </summary>
228.     /// <param name="pattern">The regex pattern to match against input words.</param>
229.     /// <param name="replacement">The replacement string with regex group references.</param>
230.     public InflectionRule(string pattern, string replacement)
231.     {
232.         // RegexOptions.Compiled is expensive for startup with many rules;
233.         // use interpreted regex which is sufficient for matching short strings.
234.         _regex = new Regex(pattern, RegexOptions.IgnoreCase);
235.         _replacement = replacement;
236.     }
237. 
238.     /// <summary>
239.     /// Attempts to apply this rule to the given word.
240.     /// </summary>
241.     /// <param name="word">The word to transform.</param>
242.     /// <returns>The transformed word if the pattern matches; otherwise, null.</returns>
243.     public string? Apply(string word)
244.     {
245.         if (!_regex.IsMatch(word))
246.         {
247.             return null;
248.         }
249. 
250.         return _regex.Replace(word, _replacement);
251.     }
252. }
